pwsh -NoProfile -Command '
$errs = $null
foreach ($f in @("site/install.ps1", "site/setup.ps1")) {
  $tokens = $null; $parsErrs = $null
  [System.Management.Automation.Language.Parser]::ParseFile((Resolve-Path $f), [ref]$tokens, [ref]$parsErrs) | Out-Null
  if ($parsErrs -and $parsErrs.Count -gt 0) { Write-Host "SYNTAX FAIL $f"; $parsErrs | ForEach-Object { Write-Host $_.Message } }
  else { Write-Host "SYNTAX OK $f" }
}
'

pwsh -NoProfile -Command '
foreach ($f in @("site/install.ps1", "site/setup.ps1")) {
  $bytes = [IO.File]::ReadAllBytes((Resolve-Path $f))
  foreach ($enc in @("UTF-8", "ISO-8859-1")) {
    $text = [Text.Encoding]::GetEncoding($enc).GetString($bytes)
    $tok = $null; $err = $null
    [System.Management.Automation.Language.Parser]::ParseInput($text, [ref]$tok, [ref]$err) | Out-Null
    $n = if ($err) { $err.Count } else { 0 }
    Write-Host ("$f decoded as $enc -> parse errors: $n")
    if ($n -gt 0) { $err | Select-Object -First 2 | ForEach-Object { Write-Host ("  " + $_.Message) } }
  }
}
'
